import { BrowserRouter as Router, Routes, Route, useLocation } from "react-router-dom";
import { CSSTransition, SwitchTransition } from "react-transition-group";
import { useRef, useEffect } from "react";
import Login from "./components/Login";
import Register from "./components/Register";
import Home from "./components/Home";
import Profile from "./components/Profile";
import { API_URL, getCurrentUser, getAccessToken } from "./api/auth";
import "./styles/App.css";


function AnimatedRoutes() {
    const location = useLocation();
    const nodeRef = useRef(null);

    return (
        <SwitchTransition mode="out-in">
            <CSSTransition
                key={location.pathname}
                nodeRef={nodeRef}
                timeout={400}
                classNames={
                    location.pathname === "/login"
                        ? "slide-right"
                        : location.pathname === "/register"
                            ? "slide-left"
                            : ""
                }
                unmountOnExit
            >
                <div ref={nodeRef}>
                    <Routes location={location}>
                        <Route path="/login" element={<Login />} />
                        <Route path="/register" element={<Register />} />
                        <Route path="/" element={<Home />} />
                        <Route path="/profile" element={<Profile />} />
                    </Routes>
                </div>
            </CSSTransition>
        </SwitchTransition>
    );
}

function RoleUpdateSubscriber({ setCurrentUser }) {
    useEffect(() => {
        const userId = getCurrentUser()?.id;
        if (!userId) return;

        const evtSource = new EventSource(`${API_URL}/users/sse/role-updates`);

        evtSource.onmessage = async (event) => {
            console.log("Role update received:", event.data);

            // Обновляем токен текущего пользователя
            try {
                const response = await fetch(`${API_URL}/auth/force-refresh/${userId}`, {
                    method: "POST",
                    headers: {
                        "Authorization": "Bearer " + getAccessToken(),
                        "Content-Type": "application/json"
                    }
                });

                if (response.ok) {
                    const newTokens = await response.json();
                    saveTokens(newTokens.accessToken, newTokens.refreshToken);
                    setCurrentUser(getCurrentUser());
                    console.log("Token refreshed due to role change");
                }
            } catch (error) {
                console.error("Failed to refresh token:", error);
            }
        };

        evtSource.onerror = (err) => {
            console.error("SSE error", err);
            evtSource.close();
        };

        return () => evtSource.close();
    }, [setCurrentUser]);
}



export default function App() {
    return (
        <Router>
            <RoleUpdateSubscriber />
            <AnimatedRoutes />
        </Router>
    );
}
